type Slot = std::sync::Weak<dyn Fn(&Price) + Send + Sync>;

struct Bus(std::sync::Mutex<Vec<Slot>>);

impl Bus {
    fn publish(&self, price: &Price) {
        let live: Vec<_> = self.0.lock().unwrap().iter()
            .filter_map(std::sync::Weak::upgrade).collect();
        for f in live { f(price); }   // called outside the lock
    }
}
